"""Nginx combined-log input and plain export formats."""
from dataclasses import dataclass
import os, re, gzip

class AppError(Exception):
    pass

def rust_string(s):
    # Debug-style quoted strings used in diagnostics (not in the exports).
    out='"'
    for ch in str(s):
        out += {'"':'\\"','\\':'\\\\','\n':'\\n','\r':'\\r','\t':'\\t','\0':'\\0'}.get(ch, ch if ord(ch)>=32 else '\\u{%x}'%ord(ch))
    return out+'"'

def number(text, bits=64):
    if text=='': raise ValueError('Empty')
    if not re.fullmatch(r'\+?[0-9]+',text): raise ValueError('InvalidDigit')
    n=int(text)
    if n >= 1<<bits: raise ValueError('PosOverflow')
    return n

METHODS={'GET','HEAD','POST','PUT','DELETE','CONNECT','OPTIONS','TRACE','PATCH'}
MONTHS={s:i+1 for i,s in enumerate('Jan Feb Mar Apr May Jun Jul Aug Sep Oct Nov Dec'.split())}

@dataclass
class Hit:
    date: tuple
    time: tuple
    remote_addr: str
    method: str
    path: str
    status: int
    bytes_sent: int
    referer: str
    raw: str
    day_index: int=0

    def date_text(self):
        return '%04d/%02d/%02d'%self.date
    def time_text(self):
        return '%02d:%02d:%02d'%self.time
    def datetime(self):
        return self.date+self.time

# Fields not present in the default format are deliberately not interpreted.
LINE=re.compile(r'^([^ ]*) [^\[]*\[([^\]]*)\][^\"]*"([^\"]*)"[^ ]* ([^ ]*) ([^ ]*) [^\"]*"([^\"]*)"')
DATE=re.compile(r'^(\d{2})/([A-Za-z]{3})/(\d{4}):(\d{2}):(\d{2}):(\d{2})')
def parse_line(line):
    m=LINE.search(line)
    if not m: return None
    ip,dt,req,status,size,ref=m.groups()
    d=DATE.match(dt)
    if not d: return None
    day,mon,year,h,mi,s=d.groups()
    if mon not in MONTHS: return None
    year,mon,day,h,mi,s=int(year),MONTHS[mon],int(day),int(h),int(mi),int(s)
    if not (1<=day<=31 and h<24 and mi<60 and s<=60): return None
    try:
        status=number(status,16); size=number(size)
    except ValueError: return None
    if ' ' in req:
        method,path=req.split(' ',1)
        method=method if method in METHODS else ('none' if method in ('','-') else 'other')
        path=path.split(' ',1)[0]
    else:
        method='none';path=req
    path=path.split('?',1)[0]
    return Hit((year,mon,day),(h,mi,s),ip,method,path,status,size,ref,line)

def io_error(e):
    if isinstance(e,UnicodeError):
        return AppError('Io(Error { kind: InvalidData, message: "stream did not contain valid UTF-8" })')
    if isinstance(e,EOFError): return AppError('Io(Kind(UnexpectedEof))')
    if isinstance(e,gzip.BadGzipFile):
        msg='invalid gzip header'
        if 'CRC' in str(e):msg='corrupt gzip stream does not have a matching checksum'
        return AppError('Io(Custom { kind: InvalidInput, error: '+rust_string(msg)+' })')
    code=getattr(e,'errno',None)
    names={2:'NotFound',13:'PermissionDenied',21:'IsADirectory',20:'NotADirectory',40:'FilesystemLoop'}
    if code is not None:
        return AppError('Io(Os { code: %d, kind: %s, message: %s })'%(code,names.get(code,'Other'),rust_string(os.strerror(code))))
    return AppError('Io(Custom { kind: InvalidInput, error: '+rust_string(str(e))+' })')

def file_lines(path):
    try:
        op=gzip.open if path.endswith('.gz') else open
        with op(path,'rt',encoding='utf-8',newline='') as f:
            for line in f:
                yield line[:-2] if line.endswith('\r\n') else (line[:-1] if line.endswith('\n') else line)
    except (OSError,UnicodeError,EOFError) as e: raise io_error(e)

def discover(paths,no_name_check=False):
    candidates=[]
    def walk(path,explicit=False,ancestors=frozenset()):
        if os.path.isdir(path):
            real=os.path.realpath(path)
            if real in ancestors: return
            try:
                entries=list(os.scandir(path))
            except OSError as e: raise io_error(e)
            for entry in entries:
                walk(os.path.join(path,entry.name),False,ancestors|{real})
        elif explicit or no_name_check or 'access.log' in os.path.basename(path):
            if os.path.isfile(path): candidates.append(path)
    for p in paths:
        if not os.path.exists(p): raise AppError('PathNotFound('+rust_string(p)+')')
        walk(p,True)
    files=[]
    for path in candidates:
        first=None
        it=file_lines(path)
        try:
            for i,line in enumerate(it):
                hit=parse_line(line)
                if hit:
                    first=hit;break
                if i==2:break
        finally: it.close()
        if first: files.append((path,first.date))
    files.sort(key=lambda item:item[1])
    if not files: raise AppError('NoLogFileFound')
    return files

def export_header(mode):
    if mode=='csv':return 'date,time,remote address,method,path,status,bytes sent,referer\n'
    if mode=='json':return '[\n'
    return ''

def export_hit(hit,mode):
    d=hit.date_text();t=hit.time_text()
    if mode=='raw': return hit.raw+'\n'
    if mode=='csv':
        return f'{d},{t},{hit.remote_addr},{hit.method},"{hit.path}",{hit.status},{hit.bytes_sent},"{hit.referer}"\n'
    return ('  {\n'
            f'    "date": "{d}",\n'
            f'    "time": "{t}",\n'
            f'    "remote_addr": "{hit.remote_addr}",\n'
            f'    "method": "{hit.method}",\n'
            f'    "path": "{hit.path}",\n'
            f'    "status": "{hit.status}",\n'
            f'    "bytes_sent": {hit.bytes_sent},\n'
            f'    "referer": "{hit.referer}"\n'
            '  }')
PY
