"""Argument vocabulary and command-line diagnostics."""
import re, os, sys
from logdata import number, rust_string

OPTIONS=[('help',None,None),('version',None,None),('color',None,'color'),
 ('key','k','KEY'),('length','l','LENGTH'),('fields','f','FIELDS'),('changes','c',None),
 ('date','d','DATE'),('ip','i','IP'),('method','m','METHOD'),('path','p','PATH'),
 ('referer','r','REFERER'),('status','s','STATUS'),('time','t','TIME'),
 ('all','a',None),('no-name-check',None,None),('output','o','OUTPUT'),('silent-load',None,None)]
LONG={n:(n,s,v) for n,s,v in OPTIONS}
SHORT={s:(n,s,v) for n,s,v in OPTIONS if s}

class CliError(Exception):
    pass

def label(name):
    v=LONG[name][2]
    return '--'+name+(' <'+v+'>' if v else '')

def fields_parse(text):
    result=list('dsrp') if text.startswith(('+','-')) else []
    remove=False
    for tok in re.findall(r'[+-]|[^\s,+-]+',text):
        if tok in '+-':remove=tok=='-';continue
        initial=tok[0].lower()
        if initial not in 'adtmsirp':raise ValueError("unrecognized field start "+repr(initial))
        fs=list('dtmsirp') if initial=='a' else [initial]
        for f in fs:
            if f in result: result.remove(f)
            if not remove:result.append(f)
    return result

def parse(argv):
    result={'color':'auto','key':'hits','length':1,'fields':list('dsrp'),'output':'tables','files':[]}
    seen=[]
    prog=os.path.basename(sys.argv[0])
    # The application name in the generated executable is its invoked filename.
    if prog.endswith('.py'):prog='executable'
    def usage(extra=None):
        flags=[label(n) for n in seen if n in ('help','version','all','changes','no-name-check','silent-load')]
        if extra: flags.append(label(extra))
        if not flags: flags=['[OPTIONS]']
        return 'Usage: '+prog+' '+' '.join(flags)+' [FILES]...\n'
    def unexpected(arg):
        suggestion=None
        # Long-option misspellings get a nearest-name hint.
        if arg.startswith('--'):
            def jw(a,b):
                # Jaro distance, sufficient to mirror typo hints without external libraries.
                distance=max(len(a),len(b))//2-1;ma=[False]*len(a);mb=[False]*len(b)
                for i,ch in enumerate(a):
                    for j in range(max(0,i-distance),min(len(b),i+distance+1)):
                        if not mb[j] and ch==b[j]:ma[i]=True;mb[j]=True;break
                matches=sum(ma)
                if not matches:return 0
                aa=[c for c,m in zip(a,ma) if m];bb=[c for c,m in zip(b,mb) if m]
                trans=sum(x!=y for x,y in zip(aa,bb))/2
                return (matches/len(a)+matches/len(b)+(matches-trans)/matches)/3
            scores=[(jw(arg[2:],n),n) for n in LONG]
            score,name=max(scores)
            if score>0.85:suggestion=name
        msg=f"error: unexpected argument '{arg}' found\n\n"
        if suggestion:
            msg+=f"  tip: a similar argument exists: '--{suggestion}'\n\n"+usage(suggestion)
        else:msg+=f"  tip: to pass '{arg}' as a value, use '-- {arg}'\n\n"+usage()
        raise CliError(msg)
    def set_value(name,value):
        lab=label(name)
        if name in seen:
            raise CliError(f"error: the argument '{lab}' cannot be used multiple times\n\n"+'Usage: '+prog+' [OPTIONS] [FILES]...\n')
        seen.append(name)
        if LONG[name][2] is None:
            if value is not None:
                allopts='|'.join(label(n) for n,_,_ in OPTIONS)+'|FILES'
                raise CliError(f"error: unexpected value '{value}' for '--{name}' found; no more were expected\n\nUsage: {prog} <{allopts}>\n")
            result[name]=True;return
        try:
            if name=='color':
                if value not in ('auto','yes','no'):
                    raise CliError(f"error: invalid value '{value}' for '{lab}'\n  [possible values: auto, yes, no]\n")
            elif name in ('key','output'):
                aliases=({'h':'hits','hits':'hits','b':'bytes','bytes':'bytes'} if name=='key' else
                         {'t':'tables','tables':'tables','j':'json','json':'json','r':'raw','raw':'raw','c':'csv','csv':'csv'})
                if value.lower() not in aliases:raise ValueError(f'unrecognized {name} '+rust_string(value))
                value=aliases[value.lower()]
            elif name=='length':
                try:value=number(value)
                except ValueError as e:
                    raise ValueError({'Empty':'cannot parse integer from empty string','InvalidDigit':'invalid digit found in string','PosOverflow':'number too large to fit in target type'}[str(e)])
            elif name=='fields':value=fields_parse(value)
        except ValueError as e:raise CliError(f"error: invalid value '{value}' for '{lab}': {e}\n")
        result[name]=value
    i=0;positional=False
    while i<len(argv):
        arg=argv[i];i+=1
        if positional or not arg.startswith('-') or arg=='-':
            result['files'].append(arg);continue
        if arg=='--':positional=True;continue
        if arg.startswith('--'):
            key,eq,attached=arg[2:].partition('=')
            if key not in LONG:unexpected('--'+key)
            spec=LONG[key];pending=[(spec, attached if eq else None)]
        else:
            pending=[];j=1
            while j<len(arg):
                s=arg[j];j+=1
                if s not in SHORT:unexpected('-'+s)
                spec=SHORT[s]
                if spec[2] and j<len(arg):
                    pending.append((spec,arg[j:].removeprefix('=')));break
                pending.append((spec,None))
                if spec[2]:break
        for (name,short,valname),value in pending:
            if valname and value is None:
                if i<len(argv) and (not argv[i].startswith('-') or argv[i]=='-'):
                    value=argv[i];i+=1
                else:
                    if i<len(argv) and argv[i]!='--':
                        candidate=argv[i]
                        known=(candidate[2:].split('=')[0] in LONG if candidate.startswith('--') else len(candidate)>1 and candidate[1] in SHORT)
                        if not known:unexpected(candidate if candidate.startswith('--') else '-'+candidate[1])
                    raise CliError(f"error: a value is required for '{label(name)}' but none was supplied\n")
            set_value(name,value)
    return result
PY"}

