                entries=list(os.scandir(path))
            except OSError as e: raise io_error(e)
            for entry in entries:
                walk(os.path.join(path,entry.name),False,ancestors|{real})
        elif explicit or no_name_check or 'access.log' in os.path.basename(path):
            if os.path.isfile(path): candidates.append(path)
